+  // F3: standalone CSR existence + reset-value probe. Halts the freshly-reset
+  // hart via DMI and checked-reads each address -- cmderr (an unimplemented
+  // CSR) surfaces as nullopt. No QEMU state, no run(): the read values ARE the
+  // architectural reset state. Emitted by `--probe`, consumed by andesim's
+  // gen_manifest.py to MEASURE the implemented set + reset values instead of
+  // hand-tracing RTL params. The caller must load a (spin) ELF first so the
+  // reset vector is mapped -- the hart fetches a couple instructions from it
+  // before the DMI halt takes effect (same window capture_reset_baseline uses).
+  auto probe_csrs(const std::vector<uint16_t>& addrs)
+    -> std::vector<std::pair<uint16_t, std::optional<uint64_t>>>
+  {
+    using RD = hybrid::ResumeDriver;
+    hybrid::SystemCDmiBus<PLATFORM::dmi_addr_width, PLATFORM::dmi_data_width>
+      bus{platform.dmi, platform.clk.period()};
+    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive);
+    bus.write(RD::kDmcontrol, RD::kDmcontrolDmactive | RD::kDmcontrolHaltreq);
+    hybrid::poll_until_set(bus, RD::kDmstatus, RD::kDmstatusAllhalted,
+                           "csr-probe halt");
+    // At reset mstatus.FS/VS are Off, so FP/V CSR reads raise illegal-insn
+    // (cmderr) and would mis-probe as absent. Enable them (WARL no-op on an
+    // engine without FP/V), exactly like capture_reset_baseline before its
+    // FP/V reads. mstatus's own probed value is thus FS/VS-perturbed -- a known
+    // artifact (mstatus is a base always-transported, verify-excluded CSR).
+    {
+      const uint64_t mstatus = hybrid::read_register_64(
+        bus, hybrid::regno_csr(RD::kCsrMstatus), "csr-probe mstatus");
+      uint64_t enable = mstatus;
+      if ((enable & RD::kMstatusFsMask) == 0) enable |= RD::kMstatusFsInitial;
+      if ((enable & RD::kMstatusVsMask) == 0) enable |= RD::kMstatusVsInitial;
+      if (enable != mstatus)
+        hybrid::write_register_abstract(
+          bus, hybrid::regno_csr(RD::kCsrMstatus), enable);
